CREATE INDEX IF NOT EXISTS idx_message_fts_rowid_map_session_time
    ON message_fts_rowid_map(session_id, message_time_ms);
CREATE TABLE IF NOT EXISTS message_time_backfill_state (
    id INTEGER PRIMARY KEY CHECK(id = 1),
    cursor_session_id TEXT NOT NULL DEFAULT '',
    cursor_ordinal INTEGER NOT NULL DEFAULT 0,
    completed INTEGER NOT NULL DEFAULT 0 CHECK(completed IN (0, 1)),
    updated_at INTEGER NOT NULL DEFAULT 0
);
INSERT OR IGNORE INTO message_time_backfill_state
    (id, cursor_session_id, cursor_ordinal, completed, updated_at)
VALUES (1, '', 0, 0, 0);

CREATE TABLE IF NOT EXISTS memory_embedding_watermarks (
    project_path TEXT PRIMARY KEY,
    written_memory_id INTEGER NOT NULL DEFAULT 0,
    embedded_memory_id INTEGER NOT NULL DEFAULT 0,
    updated_at INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS single_store_state (
    id INTEGER PRIMARY KEY CHECK (id = 1),
    state TEXT NOT NULL CHECK (state IN ('required', 'migrated')),
    migrated_at INTEGER,
    migrated_by TEXT,
    backup_dir TEXT,
    report_json TEXT
);
INSERT OR IGNORE INTO single_store_state(id, state) VALUES (1, 'required');

CREATE TABLE IF NOT EXISTS session_replay_decisions (
    session_id TEXT NOT NULL,
    message_id TEXT NOT NULL,
    decision TEXT NOT NULL,
    PRIMARY KEY (session_id, message_id)
) WITHOUT ROWID;

CREATE TRIGGER git_commits_fts_insert AFTER INSERT ON git_commits BEGIN
    DELETE FROM git_commits_fts WHERE rowid IN (
        SELECT fts_rowid FROM git_commit_fts_rowid_map WHERE sha = NEW.sha
    );
    DELETE FROM git_commit_fts_rowid_map WHERE sha = NEW.sha;
    INSERT INTO git_commits_fts(sha, project_path, message)
    VALUES (NEW.sha, NEW.project_path, NEW.message);
    INSERT INTO git_commit_fts_rowid_map(fts_rowid, sha)
    VALUES (last_insert_rowid(), NEW.sha);
END

CREATE TRIGGER git_commits_fts_delete AFTER DELETE ON git_commits BEGIN
    DELETE FROM git_commits_fts WHERE rowid IN (
        SELECT fts_rowid FROM git_commit_fts_rowid_map WHERE sha = OLD.sha
    );
    DELETE FROM git_commit_fts_rowid_map WHERE sha = OLD.sha;
END

CREATE TRIGGER git_commits_fts_update AFTER UPDATE OF message, project_path ON git_commits BEGIN
    DELETE FROM git_commits_fts WHERE rowid IN (
        SELECT fts_rowid FROM git_commit_fts_rowid_map WHERE sha = OLD.sha
    );
    DELETE FROM git_commit_fts_rowid_map WHERE sha = OLD.sha;
    INSERT INTO git_commits_fts(sha, project_path, message)
    VALUES (NEW.sha, NEW.project_path, NEW.message);
    INSERT INTO git_commit_fts_rowid_map(fts_rowid, sha)
    VALUES (last_insert_rowid(), NEW.sha);
END

CREATE INDEX IF NOT EXISTS idx_tags_session_message_nocase
        ON tags(session_id, message_id COLLATE NOCASE);
        CREATE INDEX IF NOT EXISTS idx_tags_session_tool_owner
        ON tags(session_id, tool_owner_message_id);

CREATE TABLE IF NOT EXISTS session_meta_collection_revisions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    session_id TEXT NOT NULL,
    column_name TEXT NOT NULL,
    revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision > 0),
    UNIQUE(session_id,column_name)
);
CREATE TRIGGER IF NOT EXISTS session_meta_chunks_revision_ai AFTER INSERT ON session_meta_chunks BEGIN
    INSERT INTO session_meta_collection_revisions(session_id,column_name,revision)
    SELECT NEW.session_id,NEW.column_name,1 WHERE 1
    ON CONFLICT(session_id,column_name) DO UPDATE SET revision=revision+1;
END;
CREATE TRIGGER IF NOT EXISTS session_meta_chunks_revision_au AFTER UPDATE ON session_meta_chunks BEGIN
    INSERT INTO session_meta_collection_revisions(session_id,column_name,revision)
    SELECT OLD.session_id,OLD.column_name,1 WHERE OLD.session_id IS NOT NEW.session_id OR OLD.column_name IS NOT NEW.column_name
    ON CONFLICT(session_id,column_name) DO UPDATE SET revision=revision+1;
    INSERT INTO session_meta_collection_revisions(session_id,column_name,revision)
    SELECT NEW.session_id,NEW.column_name,1 WHERE 1
    ON CONFLICT(session_id,column_name) DO UPDATE SET revision=revision+1;
END;
CREATE TRIGGER IF NOT EXISTS session_meta_chunks_revision_ad AFTER DELETE ON session_meta_chunks BEGIN
    INSERT INTO session_meta_collection_revisions(session_id,column_name,revision)
    SELECT OLD.session_id,OLD.column_name,1 WHERE 1
    ON CONFLICT(session_id,column_name) DO UPDATE SET revision=revision+1;
END;
